// Exact GRX classification of all-odd k-block representations at length N over D_(2p) (rotation slice, 2026-10-18).
// Clean C++ port of kblock_exact_v3.py (supersedes the never-compiled draft kblock_exact.cpp).  Same mathematics:
//  * F = k, k+2, ... with H = (F-k)/2 <= p-1 (pairs bound), R = N-F; proved prefilters R <= 3p-2 (EGZ) and, if
//    F >= 2 and N <= 4p-1, R + H <= 3p-2 (Davenport-alpha);
//  * rotation multisets Y generated by a pruned DFS using only the GRX zero pattern (no zero-sum of even length in
//    [2p-2H, 2p]);
//  * distributions of Y into k ordered runs up to cyclic rotation of the run index (theta ranges over all of Z_p^k with
//    sum 0, and a cyclic rotation of (runs, theta) is again a datum with the same GRX conditions);
//  * pattern z (bit i = run i in the + zone, bit 0 set): Phi = number of i with z_i != z_(i+1); admissible even
//    m = 2p - C, C even in [Phi, F - (k - Phi)], 0 <= m <= R; W_z = union of the signed size-m subset-sum sets;
//    theta avoids iff T(z) = sum_{z_i = +} theta_i is not in W_z for every z.
// Prints "HIT ..." for every NON-RIGID avoiding datum (up to max_print) for raw-DP re-verification in Python, then
// a SUMMARY line.  Usage: kblock_exact_v2 p N k nonrigid_only(0/1) max_print
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <functional>
using namespace std;
typedef uint32_t M;
static int P, NN, K, NONRIG, MAXPRINT;
static M FULL;
static inline M rotm(M m, int s) { s %= P; if (s < 0) s += P; if (!s) return m; return ((m << s) | (m >> (P - s))) & FULL; }
static inline M negm(M m) { M o = m & 1u; for (int v = 1; v < P; v++) if ((m >> v) & 1u) o |= 1u << (P - v); return o; }
static long long cntY = 0, cntDist = 0, avRig = 0, avNon = 0, printed = 0;

static void addCopies(vector<M>& prof, int v, int c) {  // multiset gains c copies of value v
    int maxL = (int)prof.size() - 1;
    vector<M> nw = prof;
    for (int L = 0; L <= maxL; L++) {
        M m = prof[L]; if (!m) continue;
        M acc = m;
        for (int j = 1; j <= c && L + j <= maxL; j++) { acc = rotm(acc, v); nw[L + j] |= acc; }
    }
    prof.swap(nw);
}
static bool isRigid(const vector<int>& cnt) {
    if (cnt[0]) return false;
    int x = -1;
    for (int v = 1; v < P; v++) if (cnt[v]) { if (x < 0) x = v; else if (v != x && v != P - x) return false; }
    return true;
}

static vector<vector<int>> Ys;
static int gR, gLo, gF;
static bool badProf(const vector<M>& pr) {
    for (int L = max(gLo, 2); L < (int)pr.size(); L++) if (!(L & 1) && (pr[L] & 1u)) return true;
    return false;
}
static void ydfs(int v, int left, vector<int>& cnt, vector<M> prof) {
    if (v == P - 1) {
        addCopies(prof, v, left);
        if (!badProf(prof)) { cnt[v] = left; Ys.push_back(cnt); cnt[v] = 0; }
        return;
    }
    for (int c = 0; c <= left; c++) {
        if (c) { addCopies(prof, v, 1); if (badProf(prof)) break; }
        cnt[v] = c;
        ydfs(v + 1, left - c, cnt, prof);
        cnt[v] = 0;
    }
}

static vector<vector<int>> runs;  // runs[i][v]
static vector<int> pats;
static void evalDistribution(bool rigidY) {
    cntDist++;
    int R = gR;
    vector<vector<M>> prof(K), nprof(K);
    for (int i = 0; i < K; i++) {
        int ri = 0; for (int v = 0; v < P; v++) ri += runs[i][v];
        prof[i].assign(ri + 1, 0); prof[i][0] = 1;
        for (int v = 0; v < P; v++) if (runs[i][v]) addCopies(prof[i], v, runs[i][v]);
        nprof[i].resize(ri + 1);
        for (int m = 0; m <= ri; m++) nprof[i][m] = negm(prof[i][m]);
    }
    int np = (int)pats.size();
    vector<M> W(np, 0);
    vector<int> decideAt(np);
    for (int t = 0; t < np; t++) {
        int z = pats[t];
        vector<M> comb(R + 1, 0), nw;
        comb[0] = 1; int cur = 0;
        for (int i = 0; i < K; i++) {
            const vector<M>& pr = ((z >> i) & 1) ? prof[i] : nprof[i];
            int ri = (int)pr.size() - 1;
            nw.assign(R + 1, 0);
            for (int a = 0; a <= cur; a++) {
                M ma = comb[a]; if (!ma) continue;
                for (int b = 0; b <= ri && a + b <= R; b++) {
                    M mb = pr[b]; if (!mb) continue;
                    M acc = 0;
                    for (int s = 0; s < P; s++) if ((ma >> s) & 1u) acc |= rotm(mb, s);
                    nw[a + b] |= acc;
                }
            }
            comb.swap(nw); cur += ri;
        }
        int Phi = 0;
        for (int i = 0; i < K; i++) if (((z >> i) & 1) != ((z >> ((i + 1) % K)) & 1)) Phi++;
        int Cmax = gF - (K - Phi);
        M w = 0;
        for (int C = Phi; C <= Cmax; C += 2) { int m = 2 * P - C; if (m >= 0 && m <= R) w |= comb[m]; }
        W[t] = w;
        int maxPlus = -1, maxMinus = -1;
        for (int i = 0; i < K; i++) { if ((z >> i) & 1) maxPlus = i; else maxMinus = i; }
        int d = maxPlus + 1;
        if (maxMinus >= 0) d = min(d, maxMinus + 1);
        decideAt[t] = min(d, K - 1);  // decidable once theta_0..theta_(d-1) are fixed (theta_(K-1) = -sum)
    }
    vector<vector<int>> checkAt(K);
    for (int t = 0; t < np; t++) checkAt[decideAt[t]].push_back(t);
    vector<int> th(K, 0);
    auto Tof = [&](int t, int depth) {  // depth = last assigned index
        int z = pats[t]; int T = 0;
        int maxPlus = -1; for (int i = 0; i < K; i++) if ((z >> i) & 1) maxPlus = i;
        if (maxPlus <= depth) { for (int i = 0; i <= depth; i++) if ((z >> i) & 1) T += th[i]; }
        else { for (int i = 0; i <= depth; i++) if (!((z >> i) & 1)) T -= th[i]; }
        T %= P; if (T < 0) T += P; return T;
    };
    function<void(int, int)> rec = [&](int depth, int partial) {
        if (depth == K - 1) {
            th[K - 1] = ((-partial) % P + P) % P;
            for (int t : checkAt[K - 1]) if ((W[t] >> Tof(t, K - 1)) & 1u) return;
            if (rigidY) avRig++;
            else {
                avNon++;
                if (printed < MAXPRINT) {
                    printed++;
                    printf("HIT F=%d runs=", gF);
                    for (int i = 0; i < K; i++) { if (i) printf("|"); for (int v = 0; v < P; v++) printf(v ? ",%d" : "%d", runs[i][v]); }
                    printf(" theta=");
                    for (int i = 0; i < K; i++) printf(i ? ",%d" : "%d", th[i]);
                    printf("\n");
                }
            }
            return;
        }
        for (int x = 0; x < P; x++) {
            th[depth] = x;
            bool ok = true;
            if (depth + 1 <= K - 2)
                for (int t : checkAt[depth + 1]) if ((W[t] >> Tof(t, depth)) & 1u) { ok = false; break; }
            if (ok) rec(depth + 1, (partial + x) % P);
        }
    };
    // patterns decidable at index 0 (none: d >= 1) ; start
    rec(0, 0);
}
static bool minimalRotation() {
    for (int s = 1; s < K; s++) {
        int cmp = 0;
        for (int i = 0; i < K && !cmp; i++) {
            const vector<int>& a = runs[i]; const vector<int>& b = runs[(i + s) % K];
            if (a != b) cmp = (b < a) ? -1 : 1;
        }
        if (cmp < 0) return false;
    }
    return true;
}
static void distRec(int v, const vector<int>& cnt, bool rigidY);
static void compRec(int v, int i, int left, const vector<int>& cnt, bool rigidY) {
    if (i == K - 1) { runs[i][v] = left; distRec(v + 1, cnt, rigidY); runs[i][v] = 0; return; }
    for (int a = 0; a <= left; a++) { runs[i][v] = a; compRec(v, i + 1, left - a, cnt, rigidY); }
    runs[i][v] = 0;
}
static void distRec(int v, const vector<int>& cnt, bool rigidY) {
    if (v == P) { if (minimalRotation()) evalDistribution(rigidY); return; }
    if (!cnt[v]) { distRec(v + 1, cnt, rigidY); return; }
    compRec(v, 0, cnt[v], cnt, rigidY);
}
int main(int argc, char** argv) {
    if (argc < 6) { fprintf(stderr, "usage: p N k nonrigid_only max_print\n"); return 2; }
    P = atoi(argv[1]); NN = atoi(argv[2]); K = atoi(argv[3]); NONRIG = atoi(argv[4]); MAXPRINT = atoi(argv[5]);
    FULL = (1u << P) - 1;
    for (int z = 0; z < (1 << K); z++) if (z & 1) pats.push_back(z);
    runs.assign(K, vector<int>(P, 0));
    for (int F = K; F <= NN; F += 2) {
        int R = NN - F, H = (F - K) / 2;
        if (H > P - 1) break;
        if (R > 3 * P - 2) continue;
        if (F >= 2 && NN <= 4 * P - 1 && R + H > 3 * P - 2) continue;
        gF = F; gR = R; gLo = 2 * P - 2 * H;
        Ys.clear();
        vector<int> cnt(P, 0);
        vector<M> prof(min(2 * P, R) + 1, 0); prof[0] = 1;
        ydfs(0, R, cnt, prof);
        for (auto& y : Ys) {
            bool rg = isRigid(y);
            if (NONRIG && rg) continue;
            cntY++;
            distRec(0, y, rg);
        }
        fflush(stdout);
    }
    printf("SUMMARY p=%d N=%d k=%d nonrigid_only=%d Y=%lld distributions=%lld avoid_rigid=%lld avoid_nonrigid=%lld\n",
           P, NN, K, NONRIG, cntY, cntDist, avRig, avNon);
    return 0;
}
